  "regulated_action": {
    "target_id": "t0",
    "description": "Freezing membership M-40217 for 1 month without explicit confirmation step or reason."
  },
  "applicable_norms": [
    {
      "policy_source_id": "q11",
      "interpretation": "Before freezing a membership, explicit confirmation from the member is required (\"yes\"/\"да\").",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "A membership can be frozen only if the member has a balance of 0 EUR.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "A membership can be frozen at most once per calendar year, and only if `last_freeze_year` is not the current year.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q11",
      "interpretation": "The assistant must communicate with the user in Russian and ensure all steps are followed in the correct order.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h4",
      "actor": "assistant",
      "role": "system",
      "fact": "Member M-40217 has a balance of 0 EUR (`balance_due_eur: 0`)."
    },
    {
      "source_id": "h4",
      "actor": "assistant",
      "role": "system",
      "fact": "Member M-40217 last froze membership in 2024 (`last_freeze_year: 2024`)."
